import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, positionLocal, color, mix, clamp, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ShapeGeometry, PlaneGeometry, BoxGeometry, DirectionalLight } = ctx.THREE;

  const root = new Group();
  root.name = 'testimonial-panel';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ACCENT = colors.accent ?? '#ff2a38';
  const PAPER = colors.paper ?? '#e8ecf2';
  const SURFACE = colors.surface ?? '#16161d';
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#111116' }];
  const GRAD_TOP = stops[0]?.hex ?? '#1a1a22';
  const GRAD_BOTTOM = stops[stops.length - 1]?.hex ?? '#111116';

  const disposables = [];
  const timelines = [];

  const track = (obj) => { disposables.push(obj); return obj; };

  // ---------------------------------------------------------------
  // 1) BACKDROP STAGE — 7x6 vertical engineered gradient at z=-2.5
  // ---------------------------------------------------------------
  const backdropGeo = track(new PlaneGeometry(7, 6));
  const backdropMat = track(new MeshBasicNodeMaterial());
  backdropMat.colorNode = mix(color(GRAD_BOTTOM), color(GRAD_TOP), clamp(uv().y, 0.0, 1.0));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------------------------------------------------------------
  // 2) PANEL GROUP (animated as a unit)
  // ---------------------------------------------------------------
  const panelGroup = new Group();
  root.add(panelGroup);

  const PANEL_W = 3.4;
  const PANEL_H = 1.9;
  const RADIUS = 0.06;
  const BORDER = 0.006;

  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const hw = w / 2, hh = h / 2;
    s.moveTo(-hw + r, -hh);
    s.lineTo(hw - r, -hh);
    s.quadraticCurveTo(hw, -hh, hw, -hh + r);
    s.lineTo(hw, hh - r);
    s.quadraticCurveTo(hw, hh, hw - r, hh);
    s.lineTo(-hw + r, hh);
    s.quadraticCurveTo(-hw, hh, -hw, hh - r);
    s.lineTo(-hw, -hh + r);
    s.quadraticCurveTo(-hw, -hh, -hw + r, -hh);
    return s;
  }

  // Hairline border plate (slightly larger, sits just behind the panel face)
  const borderGeo = track(new ShapeGeometry(roundedRectShape(PANEL_W + BORDER * 2, PANEL_H + BORDER * 2, RADIUS + BORDER)));
  const borderMat = track(new MeshBasicNodeMaterial());
  borderMat.colorNode = color('#26262f');
  borderMat.transparent = true;
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.004;
  panelGroup.add(borderMesh);

  // Panel face — engineered vertical gradient albedo, machined PBR
  const panelGeo = track(new ShapeGeometry(roundedRectShape(PANEL_W, PANEL_H, RADIUS)));
  const panelMat = track(new MeshStandardNodeMaterial());
  const panelT = clamp(positionLocal.y.div(float(PANEL_H)).add(0.5), 0.0, 1.0);
  panelMat.colorNode = mix(color(GRAD_BOTTOM), color(GRAD_TOP), panelT);
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.transparent = true;
  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.position.z = 0;
  panelGroup.add(panelMesh);

  // ---------------------------------------------------------------
  // 3) TEXT CONTENT (verbatim from spec, ASCII-sanitized for atlas)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const sanitize = (s) => String(s)
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/\u2014/g, '--')
    .replace(/[^\x20-\x7E\n]/g, '"');

  const byRole = {};
  for (const item of items) {
    if (item && item.role && !byRole[item.role]) byRole[item.role] = item;
  }

  const PAD = 0.5;                 // 2x base unit padding
  const LEFT = -PANEL_W / 2 + PAD; // left content edge
  const TOP = PANEL_H / 2 - PAD;   // top content edge

  // Oversized quotation mark — accent red, seated top-left, with a
  // dark offset duplicate behind it to read as 0.04-unit extrusion depth.
  const markGroup = new Group();
  markGroup.position.set(LEFT, TOP + 0.18, 0.05);
  panelGroup.add(markGroup);

  const markItem = byRole['quote-mark'];
  const markText = markItem ? sanitize(markItem.text) : '"';
  const markSize = markItem?.typography?.fontSize ?? 62;

  const markShadow = ctx.fontAtlas.createText(markText, {
    fontSize: markSize,
    color: '#0b0b10',
    align: 'left',
  });
  markShadow.position.set(0.012, -0.012, -0.04);
  markGroup.add(markShadow);

  const markFront = ctx.fontAtlas.createText(markText, {
    fontSize: markSize,
    color: ACCENT,
    align: 'left',
  });
  markFront.position.set(0, 0, 0);
  markGroup.add(markFront);

  // Quote body — floats translateZ +0.03 above the panel face
  const quoteItem = byRole['quote'];
  if (quoteItem) {
    const quote = ctx.fontAtlas.createText(sanitize(quoteItem.text), {
      fontSize: quoteItem.typography?.fontSize ?? 20,
      color: PAPER,
      align: 'left',
      maxWidthPx: 480,
    });
    quote.position.set(LEFT, TOP - 0.62 - 0.25, 0.03);
    panelGroup.add(quote);
  }

  // Attribution row — accent rule + mono name + caption
  const ATTR_Y = -PANEL_H / 2 + PAD - 0.05;

  const ruleGeo = track(new BoxGeometry(0.2, 0.02, 0.01));
  const ruleMat = track(new MeshStandardNodeMaterial());
  ruleMat.colorNode = color(ACCENT);
  ruleMat.emissiveNode = color(ACCENT).mul(1.4);
  ruleMat.roughness = 0.5;
  ruleMat.metalness = 0.3;
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(LEFT + 0.1, ATTR_Y + 0.11, 0.03);
  panelGroup.add(rule);

  const attrItem = byRole['attribution'];
  if (attrItem) {
    const attr = ctx.fontAtlas.createText(sanitize(attrItem.text), {
      fontSize: attrItem.typography?.fontSize ?? 13,
      color: PAPER,
      align: 'left',
      letterSpacingPx: 1.1,
    });
    attr.position.set(LEFT + 0.28, ATTR_Y + 0.11, 0.03);
    panelGroup.add(attr);
  }

  const capItem = byRole['caption'];
  if (capItem) {
    const cap = ctx.fontAtlas.createText(sanitize(capItem.text), {
      fontSize: capItem.typography?.fontSize ?? 9,
      color: '#8a8f99',
      align: 'left',
      letterSpacingPx: 1.2,
    });
    cap.position.set(LEFT + 0.28, ATTR_Y - 0.04, 0.03);
    panelGroup.add(cap);
  }

  // ---------------------------------------------------------------
  // 4) FOREGROUND ACCENT PLANE — third depth layer, machined sliver
  // ---------------------------------------------------------------
  const sliverGeo = track(new BoxGeometry(0.025, 0.5, 0.025));
  const sliverMat = track(new MeshStandardNodeMaterial());
  sliverMat.colorNode = color(SURFACE);
  sliverMat.roughness = 0.5;
  sliverMat.metalness = 0.55;
  const sliver = new Mesh(sliverGeo, sliverMat);
  sliver.position.set(-2.35, -0.75, 0.7);
  sliver.rotation.z = 0.06;
  root.add(sliver);

  // ---------------------------------------------------------------
  // 5) NODE-LOCAL RIM LIGHT — accent hue, raking from behind-right
  //    (scene provides ambient 0.6 + key 1.2; rim kept <= 1.0)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(ACCENT, 0.8);
  rim.position.set(2.5, 1.2, -1.5);
  rim.target = panelMesh;
  root.add(rim);

  // ---------------------------------------------------------------
  // 6) MOUNT MOTION — fade-up panel, then weighted-settle quote mark
  // ---------------------------------------------------------------
  panelGroup.position.y = -0.2;
  panelMat.opacity = 0;
  borderMat.opacity = 0;
  markGroup.scale.setScalar(1.04);

  const tl = gsap.timeline();
  timelines.push(tl);

  tl.to(panelGroup.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(panelMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(borderMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(markGroup.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.5);
  // The piece rests with weight — no idle motion.

  // ---------------------------------------------------------------
  // 7) CINEMATIC PRIMITIVES (none declared; loop kept for contract)
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives[primitive.name];
    if (apply) primitiveHandles.push(apply(panelGroup, primitive.params ?? {}));
  }

  // ---------------------------------------------------------------
  // 8) HANDLERS + CLEANUP
  // ---------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const h of primitiveHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
    root.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose?.();
        const m = obj.material;
        if (Array.isArray(m)) m.forEach((mm) => mm?.dispose?.());
        else m?.dispose?.();
      }
    });
    rim.dispose?.();
  };

  return root;
}
